import{_ as n,o as a,c as t,a as i}from"./app.DkoUFz-u.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"backend/architecture/service-mesh/observability.md","filePath":"backend/architecture/service-mesh/observability.md"}'),r={name:"backend/architecture/service-mesh/observability.md"};function l(e,s,o,p,g,h){return a(),t("div",null,[...s[0]||(s[0]=[i(`<p>服务网格通过非侵入式的方式，为微服务提供了强大的可观测性能力，让你无需修改代码就能全面掌握服务的运行状态。其核心可观测性支柱包括：<strong>指标（Metrics）</strong>、<strong>链路追踪（Traces）</strong> 和 <strong>日志（Logs）</strong>。下面这份学习笔记将帮你系统性地理解这些内容。</p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_140thh">graph TD</span></span>
<span class="line"><span class="__shiki_140thh">    A[服务网格可观测性] --&gt; B1[指标]</span></span>
<span class="line"><span class="__shiki_140thh">    A --&gt; B2[分布式链路追踪]</span></span>
<span class="line"><span class="__shiki_140thh">    A --&gt; B3[访问日志]</span></span>
<span class="line"><span class="__shiki_140thh">    </span></span>
<span class="line"><span class="__shiki_140thh">    B1 --&gt; C1[四大黄金指标]</span></span>
<span class="line"><span class="__shiki_140thh">    B1 --&gt; C2[与Prometheus集成]</span></span>
<span class="line"><span class="__shiki_140thh">    B1 --&gt; C3[通过Grafana可视化]</span></span>
<span class="line"><span class="__shiki_140thh">    </span></span>
<span class="line"><span class="__shiki_140thh">    B2 --&gt; C4[基本概念: Trace &amp; Span]</span></span>
<span class="line"><span class="__shiki_140thh">    B2 --&gt; C5[上下文传播 header]</span></span>
<span class="line"><span class="__shiki_140thh">    B2 --&gt; C6[与Jaeger/Zipkin集成]</span></span>
<span class="line"><span class="__shiki_140thh">    </span></span>
<span class="line"><span class="__shiki_140thh">    B3 --&gt; C7[完整请求记录]</span></span>
<span class="line"><span class="__shiki_140thh">    C1 --&gt; D1[延迟]</span></span>
<span class="line"><span class="__shiki_140thh">    C1 --&gt; D2[流量]</span></span>
<span class="line"><span class="__shiki_140thh">    C1 --&gt; D3[错误]</span></span>
<span class="line"><span class="__shiki_140thh">    C1 --&gt; D4[饱和度]</span></span></code></pre></div><h3 id="🔍-理解三大支柱" tabindex="-1">🔍 理解三大支柱 <a class="header-anchor" href="#🔍-理解三大支柱" aria-label="Permalink to &quot;🔍 理解三大支柱&quot;">​</a></h3><p>服务网格的可观测性主要围绕以下三个维度展开，它们共同提供了系统运行的全景视图：</p><ol><li><p><strong>指标</strong> 指标是数值化的聚合数据，用于监控服务的总体健康度和性能趋势。在Istio中，指标主要基于<strong>四大黄金指标</strong>进行构建：</p><ul><li><strong>延迟</strong>：服务处理请求所需的时间，尤其需要关注失败请求的延迟。</li><li><strong>流量</strong>：衡量系统需求的指标，例如每秒HTTP请求数。</li><li><strong>错误</strong>：请求失败的比率。</li><li><strong>饱和度</strong>：服务资源的使用程度。</li></ul></li><li><p><strong>分布式链路追踪</strong> 链路追踪记录了单个请求在分布式系统中流经多个服务的完整路径，形成一条<strong>追踪链</strong>，极大地简化了跨服务问题的定位和性能分析。其核心概念包括：</p><ul><li><strong>Trace</strong>：代表一个端到端的事务，是分布式系统中的一次完整请求。</li><li><strong>Span</strong>：表示一个服务内部的逻辑工作单元，是追踪的最小单位。多个Span按因果关系组织起来，就构成了一条Trace。</li><li><strong>上下文传播</strong>：为了实现追踪，服务网格会注入（如Zipkin使用的B3 Header）并在服务间传递特定的HTTP头。<strong>你的应用需要主动传播这些Header</strong>，才能构建完整的调用链。</li></ul></li><li><p><strong>访问日志</strong> 日志记录了每个请求的详细信息，包括源和目标的元数据。它提供了<strong>单个服务实例</strong>级别上最详尽的流量洞察，是问题排查和审计的重要依据。</p></li></ol><h3 id="🛠️-核心组件与工具" tabindex="-1">🛠️ 核心组件与工具 <a class="header-anchor" href="#🛠️-核心组件与工具" aria-label="Permalink to &quot;🛠️ 核心组件与工具&quot;">​</a></h3><p>服务网格的可观测性依赖于一套强大的工具链：</p><ol><li><p><strong>指标与监控</strong></p><ul><li><strong>Prometheus</strong>：作为主流的开源监控工具，它通过<strong>拉取模式</strong>收集和存储时间序列数据。服务网格的Sidecar代理（如Envoy）会暴露指标端点，供Prometheus抓取。</li><li><strong>Grafana</strong>：一个强大的数据可视化平台，它从Prometheus等数据源读取指标数据，并创建丰富的监控仪表盘，让你能直观地观察系统状态。</li></ul></li><li><p><strong>链路追踪后端</strong></p><ul><li><strong>Jaeger</strong>：一个开源的分布式追踪系统，兼容OpenTracing API。它的架构包含<strong>Agent</strong>、<strong>Collector</strong>、<strong>Query</strong>以及后端存储等组件。</li><li><strong>Zipkin</strong>：另一个流行的分布式追踪系统。服务网格可以将其追踪数据上报给Zipkin或兼容其API的后端。</li></ul></li><li><p><strong>服务网格与代理</strong></p><ul><li><strong>Envoy</strong>：作为服务网格中常见的数据平面代理，它运行在每个微服务旁边，以Sidecar模式<strong>接管服务的进出流量</strong>，并负责生成指标、日志和追踪数据。</li></ul></li></ol><h3 id="📋-实施与注意事项" tabindex="-1">📋 实施与注意事项 <a class="header-anchor" href="#📋-实施与注意事项" aria-label="Permalink to &quot;📋 实施与注意事项&quot;">​</a></h3><p>在实际应用中，有几个关键点需要特别注意：</p><ol><li><p><strong>应用代码的微小改造</strong> 如之前所述，为了形成完整的分布式追踪链路，你的应用程序需要<strong>传播链路追踪的Header</strong>。这意味着，当应用收到一个包含特定Header（如B3 Header）的请求时，需要将这些Header原封不动地放入它发往下游服务的请求中。服务网格的代理无法自动完成这个操作，因为它不了解应用内部的调用逻辑。</p></li><li><p><strong>性能考量</strong> 开启可观测性功能，尤其是高采样率的链路追踪，会对系统性能（如CPU资源）产生一定影响。在生产环境中，一个常见的做法是<strong>调整采样率</strong>，只收集一部分请求的追踪数据，以在可观测性和资源消耗之间取得平衡。</p></li><li><p><strong>集成自有系统</strong> 服务网格通常允许你集成自己搭建的链路追踪系统（如Jaeger）。基本要求是这些系统需要<strong>支持Zipkin等协议</strong>。在阿里云ASM中，你可以在配置中将Zipkin Service指向你自己的追踪后端。</p></li></ol><h3 id="💡-最佳实践总结" tabindex="-1">💡 最佳实践总结 <a class="header-anchor" href="#💡-最佳实践总结" aria-label="Permalink to &quot;💡 最佳实践总结&quot;">​</a></h3><ul><li><strong>利用服务网格的非侵入优势</strong>：将可观测性逻辑（如数据收集）从业务代码中剥离，交由服务网格处理，降低开发复杂性。</li><li><strong>多维数据关联分析</strong>：在排查复杂问题时，不要孤立地看某一种数据。例如，可以先通过<strong>指标</strong>发现错误率上升，然后利用<strong>链路追踪</strong>定位到有问题的Trace，最后通过<strong>日志</strong>查看该请求的详细错误信息。</li><li><strong>合理配置采样率</strong>：根据实际业务需求和资源情况，为分布式追踪设置一个合适的采样率，避免对性能造成过大影响。</li></ul><p>希望这份笔记能帮助你建立起服务网格可观测性的知识框架！如果你对某个工具的具体配置或某种概念的细节特别感兴趣，我很乐意提供更深入的探讨。</p>`,14)])])}const d=n(r,[["render",l]]);export{_ as __pageData,d as default};
